<main class="card">
  <h1>Créer un compte</h1>
  <p class="intro">Tous les champs sont obligatoires.</p>

  <p class="success" id="success" role="status"></p>

  <!-- Ajoutez les attributs action et method pour envoyer réellement les données à un serveur. -->
  <form id="signup-form" novalidate>
    <div class="field">
      <label for="fullname">Nom complet</label>
      <input type="text" id="fullname" name="fullname" autocomplete="name"
             required aria-describedby="fullname-error">
      <p class="error" id="fullname-error" aria-live="polite"></p>
    </div>

    <div class="field">
      <label for="email">Adresse e-mail</label>
      <input type="email" id="email" name="email" autocomplete="email"
             placeholder="prenom.nom@exemple.fr"
             required aria-describedby="email-error">
      <p class="error" id="email-error" aria-live="polite"></p>
    </div>

    <div class="field">
      <label for="website">Site web</label>
      <input type="url" id="website" name="website" autocomplete="url"
             placeholder="https://exemple.fr"
             required aria-describedby="website-error">
      <p class="error" id="website-error" aria-live="polite"></p>
    </div>

    <div class="field">
      <label for="password">Mot de passe</label>
