        <input type="password" id="password" name="password" autocomplete="new-password"
               required aria-describedby="password-hint password-error">
        <button type="button" class="toggle" id="toggle-password"
                aria-controls="password" aria-label="Afficher le mot de passe">Afficher</button>
      </div>
      <p class="hint" id="password-hint">Au moins 8 caractères, dont une lettre et un chiffre.</p>
      <p class="error" id="password-error" aria-live="polite"></p>
    </div>

    <button type="submit" class="submit">S’inscrire</button>
  </form>
</main>

<script>
(function () {
  'use strict';

  const form = document.getElementById('signup-form');
  const success = document.getElementById('success');
  const toggle = document.getElementById('toggle-password');
  const fields = ['fullname', 'email', 'website', 'password'].map(function (id) {
    return document.getElementById(id);
  });

  // Analyse l'adresse du site ; accepte « exemple.fr » en ajoutant https://.
  // Renvoie un objet URL si l'adresse est valide, sinon null.
  function parseWebsite(raw) {
    const value = raw.trim();
    if (!value || /\s/.test(value)) return null;

    const candidate = /^https?:\/\//i.test(value) ? value : 'https://' + value;
    let url;
    try {
      url = new URL(candidate);
    } catch (e) {
      return null;
    }
    if (url.username || url.password) return null;

    const labels = url.hostname.split('.');
    if (labels.length < 2) return null;
    const labelsValid = labels.every(function (label) {
      return /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i.test(label);
    });
    if (!labelsValid) return null;

    const tld = labels[labels.length - 1];
    if (tld.length < 2 || !/[a-z]/i.test(tld)) return null;

    return url;
  }

  // Chaque validateur renvoie un message d'erreur, ou une chaîne vide si la valeur est valide.
  const validators = {
    fullname: function (value) {
      const v = value.trim();
      if (!v) return 'Veuillez saisir votre nom complet.';
      if (v.length < 2 || !/\p{L}/u.test(v)) return 'Ce nom ne semble pas valide.';
      if (v.length > 100) return 'Le nom ne doit pas dépasser 100 caractères.';
      return '';
    },

    email: function (value) {
      const v = value.trim();
      if (!v) return 'Veuillez saisir votre adresse e-mail.';
      if (v.length > 254 || !/^[^\s@]+@[^\s@.]+(\.[^\s@.]+)*\.[^\s@.]{2,}$/.test(v)) {
        return 'Adresse e-mail invalide (exemple : nom@exemple.fr).';
      }
      return '';
    },

    website: function (value) {
      if (!value.trim()) return 'Veuillez saisir l’adresse de votre site web.';
      if (!parseWebsite(value)) return 'Adresse invalide (exemple : https://exemple.fr).';
      return '';
    },

    password: function (value) {
      if (!value) return 'Veuillez choisir un mot de passe.';
      if (value.length < 8) return 'Le mot de passe doit contenir au moins 8 caractères.';
      if (!/\p{L}/u.test(value) || !/\d/.test(value)) {
        return 'Le mot de passe doit contenir au moins une lettre et un chiffre.';
      }
      return '';
    }
  };

  function setError(input, message) {
    document.getElementById(input.id + '-error').textContent = message;
    if (message) {
      input.setAttribute('aria-invalid', 'true');
    } else {
      input.removeAttribute('aria-invalid');
    }
  }

  function validateField(input) {
    const message = validators[input.id](input.value);
    setError(input, message);
    return !message;
  }

  function setPasswordVisible(visible) {
    const password = document.getElementById('password');
    password.type = visible ? 'text' : 'password';
    toggle.textContent = visible ? 'Masquer' : 'Afficher';
    toggle.setAttribute('aria-label', (visible ? 'Masquer' : 'Afficher') + ' le mot de passe');
  }

  fields.forEach(function (input) {
    // À la sortie du champ : on valide seulement si quelque chose a été saisi.
    input.addEventListener('blur', function () {
      if (input.value !== '') validateField(input);
    });

    // Pendant la saisie : l'erreur disparaît dès que la valeur devient valide.
    input.addEventListener('input', function () {
      success.textContent = '';
      if (input.getAttribute('aria-invalid') === 'true') validateField(input);
    });
  });

  toggle.addEventListener('click', function () {
    setPasswordVisible(document.getElementById('password').type === 'password');
  });

  form.addEventListener('submit', function (event) {
    let firstInvalid = null;
    fields.forEach(function (input) {
      if (!validateField(input) && !firstInvalid) firstInvalid = input;
    });

    if (firstInvalid) {
      event.preventDefault();
      success.textContent = '';
      firstInvalid.focus();
      return;
    }

    // Normalisation des valeurs avant l'envoi.
    const fullname = document.getElementById('fullname');
    const email = document.getElementById('email');
    const website = document.getElementById('website');
    fullname.value = fullname.value.trim().replace(/\s+/g, ' ');
    email.value = email.value.trim();
    website.value = parseWebsite(website.value).href;

    // Si le formulaire possède un attribut action, l'envoi natif se poursuit.
    if (form.hasAttribute('action')) return;

    // Sinon (page de démonstration sans serveur), on affiche une confirmation.
    event.preventDefault();
    const name = fullname.value;
    form.reset();
    setPasswordVisible(false);
    fields.forEach(function (input) { setError(input, ''); });
    success.textContent = 'Merci, ' + name + ' ! Toutes les informations sont valides.';
  });
})();
</script>
